CREATE OR REPLACE FUNCTION public.rotate_calendar_token()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
